create extension if not exists pgcrypto;create table if not exists public.projects(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,idea text not null,languages text,status text not null default 'draft',specification jsonb,github_repository_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.projects enable row level security;create policy "Accès public temporaire aux projets" on public.projects for all using (true) with check (true);